package com.rpb.reservation.workforce.statutory;
import com.rpb.reservation.workforce.domain.WorkforceException;import java.math.*;import java.net.URI;import java.util.*;
/** Declarative rate data, never executable expressions. Decimal values cross API boundaries as strings. */
public record StatutoryPolicyConfig(int schemaVersion,String owCeiling,List<AgeBand> ageBands,List<WageBand> wageBands,List<Table> tables,Sdl sdl,String totalCpfRounding,String employeeCpfRounding,String companySdlRounding,String cpfSource,String sdlSource,String ageTiming,String prTiming,String notes,@com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL) CdacRules.Policy cdac,@com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL) AwCapability aw) {
 public record AwCapability(String annualWageCeiling,String calculationVersion,String source){}
 public StatutoryPolicyConfig(int schemaVersion,String owCeiling,List<AgeBand> ageBands,List<WageBand> wageBands,List<Table> tables,Sdl sdl,String totalCpfRounding,String employeeCpfRounding,String companySdlRounding,String cpfSource,String sdlSource,String ageTiming,String prTiming,String notes,CdacRules.Policy cdac){this(schemaVersion,owCeiling,ageBands,wageBands,tables,sdl,totalCpfRounding,employeeCpfRounding,companySdlRounding,cpfSource,sdlSource,ageTiming,prTiming,notes,cdac,null);}
 public StatutoryPolicyConfig withAw(AwCapability value){return new StatutoryPolicyConfig(2,owCeiling,ageBands,wageBands,tables,sdl,totalCpfRounding,employeeCpfRounding,companySdlRounding,cpfSource,sdlSource,ageTiming,prTiming,notes,cdac,value);}
 public StatutoryPolicyConfig withNotes(String value){return new StatutoryPolicyConfig(schemaVersion,owCeiling,ageBands,wageBands,tables,sdl,totalCpfRounding,employeeCpfRounding,companySdlRounding,cpfSource,sdlSource,ageTiming,prTiming,value,cdac,aw);}
 public StatutoryPolicyConfig(int schemaVersion,String owCeiling,List<AgeBand> ageBands,List<WageBand> wageBands,List<Table> tables,Sdl sdl,String totalCpfRounding,String employeeCpfRounding,String companySdlRounding,String cpfSource,String sdlSource,String ageTiming,String prTiming,String notes){this(schemaVersion,owCeiling,ageBands,wageBands,tables,sdl,totalCpfRounding,employeeCpfRounding,companySdlRounding,cpfSource,sdlSource,ageTiming,prTiming,notes,null);}
 public StatutoryPolicyConfig withCdac(CdacRules.Policy value){return new StatutoryPolicyConfig(schemaVersion,owCeiling,ageBands,wageBands,tables,sdl,totalCpfRounding,employeeCpfRounding,companySdlRounding,cpfSource,sdlSource,ageTiming,prTiming,notes,value,aw);}
 public record AgeBand(String code,String name,Integer upperAge){}
 public record WageBand(String code,String name,String upperWage,String method,String rampMultiplier){}
 public record Rate(String ageCode,String employerRate,String employeeRate){}
 public record Table(String code,String name,List<Rate> rates){}
 public record Sdl(String rate,String minimum,String maximum){}
 public StatutoryPolicyConfig withOwCeiling(String value){return new StatutoryPolicyConfig(schemaVersion,value,ageBands,wageBands,tables,sdl,totalCpfRounding,employeeCpfRounding,companySdlRounding,cpfSource,sdlSource,ageTiming,prTiming,notes,cdac,aw);}
 public static BigDecimal number(String s){if(s==null||!s.matches("[0-9]{1,8}(\\.[0-9]{1,8})?"))throw WorkforceException.invalid();return new BigDecimal(s);}
 public static RoundingMode rounding(String s){if(s==null||!Set.of("HALF_UP","FLOOR","CEILING").contains(s))throw WorkforceException.invalid();return RoundingMode.valueOf(s);}
 private static void name(String s,int limit){if(s==null||s.isBlank()||s.length()>limit)throw WorkforceException.invalid();}
 private static void source(String s){try{if(s==null||s.length()>1000)throw WorkforceException.invalid();var u=URI.create(s);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw WorkforceException.invalid();}catch(IllegalArgumentException e){throw WorkforceException.invalid();}}
 public static void validate(StatutoryPolicyConfig c){
  if(c==null||!Set.of(1,2).contains(c.schemaVersion())||c.ageBands()==null||c.ageBands().isEmpty()||c.ageBands().size()>12||c.wageBands()==null||c.wageBands().size()!=4||c.tables()==null||c.tables().size()!=5||c.sdl()==null||!"next_month".equals(c.ageTiming())||!"next_month".equals(c.prTiming())||c.notes()==null||c.notes().length()>2000)throw WorkforceException.invalid();if(c.schemaVersion()==1&&c.aw()!=null||c.schemaVersion()==2&&c.aw()==null)throw WorkforceException.invalid();if(c.aw()!=null){if(number(c.aw().annualWageCeiling()).signum()<=0||number(c.aw().annualWageCeiling()).scale()>2||!"SG-OW-AW-MONTH-v2".equals(c.aw().calculationVersion()))throw WorkforceException.invalid();source(c.aw().source());if(!"HALF_UP".equals(c.totalCpfRounding())||!"FLOOR".equals(c.employeeCpfRounding()))throw WorkforceException.invalid();}var ceiling=number(c.owCeiling());if(ceiling.signum()<=0||ceiling.scale()>2)throw WorkforceException.invalid();rounding(c.totalCpfRounding());rounding(c.employeeCpfRounding());rounding(c.companySdlRounding());source(c.cpfSource());source(c.sdlSource());if(c.cdac()!=null)CdacRules.validate(c.cdac());
  var ages=new HashSet<String>();int prior=0;for(int i=0;i<c.ageBands().size();i++){var a=c.ageBands().get(i);if(a==null||a.code()==null||!a.code().matches("[A-Z0-9_]{1,40}")||!ages.add(a.code())||i==c.ageBands().size()-1&&a.upperAge()!=null||i<c.ageBands().size()-1&&(a.upperAge()==null||a.upperAge()<=prior||a.upperAge()>120))throw WorkforceException.invalid();name(a.name(),100);if(a.upperAge()!=null)prior=a.upperAge();}
  BigDecimal previous=BigDecimal.ZERO;var wageCodes=new HashSet<String>();var methods=List.of("none","employer_only","ramp","normal");for(int i=0;i<c.wageBands().size();i++){var w=c.wageBands().get(i);if(w==null||w.code()==null||!w.code().matches("[A-Z0-9_]{1,40}")||!wageCodes.add(w.code())||!methods.get(i).equals(w.method())||i==3&&w.upperWage()!=null||i<3&&w.upperWage()==null)throw WorkforceException.invalid();name(w.name(),100);var factor=number(w.rampMultiplier());if(factor.compareTo(new BigDecimal("20"))>0||w.method().equals("ramp")&&factor.signum()<=0)throw WorkforceException.invalid();if(w.upperWage()!=null){var bound=number(w.upperWage());if(bound.compareTo(previous)<=0||bound.compareTo(ceiling)>0||bound.scale()>2)throw WorkforceException.invalid();previous=bound;}}
  var codes=new HashSet<String>();for(var t:c.tables()){if(t==null||t.code()==null||!Set.of("T1","T2","T3","T4","T5").contains(t.code())||!codes.add(t.code())||t.rates()==null||t.rates().size()!=ages.size())throw WorkforceException.invalid();name(t.name(),150);var covered=new HashSet<String>();for(var r:t.rates()){if(r==null||r.ageCode()==null||!ages.contains(r.ageCode())||!covered.add(r.ageCode()))throw WorkforceException.invalid();var er=number(r.employerRate());var ee=number(r.employeeRate());if(er.add(ee).compareTo(BigDecimal.ONE)>0)throw WorkforceException.invalid();}}
  if(number(c.sdl().rate()).compareTo(BigDecimal.ONE)>0||number(c.sdl().minimum()).compareTo(number(c.sdl().maximum()))>0||number(c.sdl().minimum()).scale()>2||number(c.sdl().maximum()).scale()>2)throw WorkforceException.invalid();
 }
}
